import React, { useState } from "react";
import axios from "axios";

const symptomsList = [
  "fever",
  "cough",
  "headache",
  "stomach_pain",
  "vomiting",
  "fatigue",
  "chest_pain",
  "breathing_difficulty",
  "diarrhoea",
  "weight_loss"
];

function SymptomForm() {
  const [selectedSymptoms, setSelectedSymptoms] = useState([]);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);

  const toggleSymptom = (symptom) => {
    if (selectedSymptoms.includes(symptom)) {
      setSelectedSymptoms(selectedSymptoms.filter(s => s !== symptom));
    } else {
      setSelectedSymptoms([...selectedSymptoms, symptom]);
    }
  };

  const submit = async () => {
    setLoading(true);
    try {
      const res = await axios.post("http://127.0.0.1:5000/predict", {
        symptoms: selectedSymptoms
      });
      setResult(res.data);
    } catch (err) {
      alert("Backend not running!");
    }
    setLoading(false);
  };

  return (
    <div style={{padding:"20px", fontFamily:"Arial"}}>
      <h1>🩺 AI Health Symptom Checker</h1>

      <h3>Select Symptoms:</h3>
      {symptomsList.map(sym => (
        <div key={sym}>
          <input type="checkbox" onChange={() => toggleSymptom(sym)} />
          {sym}
        </div>
      ))}

      <br />
      <button onClick={submit}>Predict Disease</button>

      {loading && <p>Predicting...</p>}

      {result && (
        <div style={{marginTop:"20px", padding:"10px", border:"2px solid black"}}>
          <h2>Disease: {result.disease}</h2>
          <h2>Urgency: {result.urgency}</h2>

          {result.urgency === "High" && (
            <h2 style={{color:"red"}}>⚠️ EMERGENCY! Visit Doctor Immediately!</h2>
          )}
        </div>
      )}
    </div>
  );
}

export default SymptomForm;
